"use client";

import { useId, useState } from "react";
import { CARD_FRAME as SHARED_CARD_FRAME } from "@/lib/card-frame";
import { cn } from "@/lib/utils";
import {
  AREA_CHART_RANGES,
  RANGE_LABEL,
  formatChange,
  formatPeriod,
  formatSeriesValue,
  isAreaChartRange,
  isRangeDistinct,
  periodTotal,
  summarizeAreaChart,
  withRange,
  withSubject,
} from "@/features/area-chart/area-chart-schema";
import type {
  AreaChartData,
  AreaChartRange,
} from "@/features/area-chart/area-chart-schema";

export type AreaChartCardState = "streaming" | "loading" | "ready" | "error";

export interface AreaChartCardProperties {
  readonly state: AreaChartCardState;
  /**
  The topic from the tool input, shown before the data arrives.
  */
  readonly topic?: string;
  readonly data?: AreaChartData;
  readonly error?: string;
  /**
  The full (Max) series behind `data`. When given, the 10Y/25Y/50Y/Max switch shows and filters it in place, with no second search. Without it, the switch is hidden and the card shows the range it was given.
  */
  readonly series?: AreaChartData;
  /**
  Shows when the series was taken. Turn it off for saved data, where the time is the save date, not the reader's now.
  */
  readonly showAsOf?: boolean;
  readonly className?: string;
}

const CARD_FRAME = `${SHARED_CARD_FRAME} w-full max-w-sm`;

const AS_OF_FORMAT = new Intl.DateTimeFormat("en-US", {
  day: "numeric",
  month: "short",
  // Fixed, so the server render and the browser agree on the date.
  timeZone: "UTC",
  year: "numeric",
});

/**
The plot's drawing box; the SVG stretches it to the card's width.
*/
const PLOT_WIDTH = 300;
const PLOT_HEIGHT = 96;
/**
How close to either edge, in percent, the hover label stops centering on the point and hugs that edge instead.
*/
const LABEL_EDGE_PERCENT = 20;

function formatAsOf(time: number) {
  return AS_OF_FORMAT.format(time);
}

function labelAlignFor(xPercent: number) {
  if (xPercent < LABEL_EDGE_PERCENT) {
    return "translate-x-0";
  }
  return xPercent > 100 - LABEL_EDGE_PERCENT
    ? "-translate-x-full"
    : "-translate-x-1/2";
}

function titleCase(value: string) {
  return value
    .trim()
    .split(/\s+/u)
    .map((word) => (word ? word.charAt(0).toUpperCase() + word.slice(1) : word))
    .join(" ");
}

function shownData(
  data: AreaChartData | undefined,
  series: AreaChartData | undefined,
  selectedRange: AreaChartRange | null,
  selectedSubject: string | null
): AreaChartData | undefined {
  const subject = data?.subjects?.find((item) => item.name === selectedSubject);
  if (data && subject) {
    return withSubject(data, subject);
  }
  return series && selectedRange ? withRange(series, selectedRange) : data;
}

function hasSubjectTabs(data: AreaChartData): boolean {
  return (data.subjects?.length ?? 0) >= 2;
}

interface Tabs {
  readonly label: string;
  readonly items: readonly {
    readonly id: string;
    readonly label: string;
    readonly isDisabled: boolean;
  }[];
  readonly selectedId: string;
}

function tabsFor(
  shown: AreaChartData,
  series: AreaChartData | undefined
): Tabs | undefined {
  if (shown.subjects && hasSubjectTabs(shown)) {
    return {
      items: shown.subjects.map(({ name }) => ({
        id: name,
        isDisabled: false,
        label: name,
      })),
      label: "Subject",
      selectedId: shown.place,
    };
  }
  if (!series) {
    return undefined;
  }
  return {
    items: AREA_CHART_RANGES.map((range) => ({
      id: range,
      isDisabled:
        range !== shown.range && !isRangeDistinct(series.points, range),
      label: RANGE_LABEL[range],
    })),
    label: "Range",
    selectedId: shown.range,
  };
}

const NEUTRAL_TONE = "text-sky-600 dark:text-sky-400";

const AreaPlot = ({
  data,
  className,
}: {
  readonly data: AreaChartData;
  readonly className?: string;
}) => {
  const gradientId = useId();
  const [active, setActive] = useState<number | null>(null);
  const width = PLOT_WIDTH;
  const height = PLOT_HEIGHT;
  const { points } = data;
  if (points.length < 2) {
    return <div className="h-24" />;
  }
  const values = points.map((point) => point.value);
  const min = Math.min(...values);
  const max = Math.max(...values);
  const span = max - min || 1;
  const coords = values.map((value, index) => [
    (index / (values.length - 1)) * width,
    height - 2 - ((value - min) / span) * (height - 4),
  ]);
  const line = coords
    .map(
      ([x, y], index) =>
        `${index === 0 ? "M" : "L"}${x.toFixed(1)},${y.toFixed(1)}`
    )
    .join(" ");

  const last = points.length - 1;
  const indexAt = (clientX: number, box: DOMRect) =>
    Math.round(
      Math.min(Math.max((clientX - box.left) / box.width, 0), 1) * last
    );

  const point = active === null ? null : points[active];
  const xPercent = active === null ? 0 : (active / last) * 100;
  const yPercent = active === null ? 0 : (coords[active][1] / height) * 100;
  const labelAlign = labelAlignFor(xPercent);

  const scrubbed = point ?? points[last];

  return (
    <div
      className={cn(
        "has-[input:focus-visible]:ring-ring relative h-24 w-full rounded has-[input:focus-visible]:ring-2",
        className
      )}
    >
      <svg
        viewBox={`0 0 ${width} ${height}`}
        preserveAspectRatio="none"
        aria-hidden
        className="size-full"
      >
        <defs>
          <linearGradient id={gradientId} x1="0" x2="0" y1="0" y2="1">
            <stop offset="0%" stopColor="currentColor" stopOpacity={0.22} />
            <stop offset="100%" stopColor="currentColor" stopOpacity={0} />
          </linearGradient>
        </defs>
        <path
          d={`${line} L${width},${height} L0,${height} Z`}
          fill={`url(#${gradientId})`}
        />
        <path
          d={line}
          fill="none"
          stroke="currentColor"
          strokeWidth={1.5}
          strokeLinejoin="round"
          vectorEffect="non-scaling-stroke"
        />
      </svg>

      {point ? (
        <>
          <div
            aria-hidden
            className="bg-border pointer-events-none absolute inset-y-0 w-px"
            style={{ left: `${xPercent}%` }}
          />
          <div
            aria-hidden
            className="ring-card pointer-events-none absolute size-2 -translate-x-1/2 -translate-y-1/2 rounded-full bg-current ring-2"
            style={{ left: `${xPercent}%`, top: `${yPercent}%` }}
          />
          <div
            aria-hidden
            className={cn(
              "bg-popover text-popover-foreground pointer-events-none absolute top-0 rounded-md border px-2 py-1 text-xs whitespace-nowrap shadow-sm",
              labelAlign
            )}
            style={{ left: `${xPercent}%` }}
          >
            <span className="font-semibold tabular-nums">
              {formatSeriesValue(point.value, data.scale, false)}
            </span>
            <span className="text-muted-foreground ml-2 tabular-nums">
              {point.year}
            </span>
          </div>
        </>
      ) : null}

      {/* A native range under the pointer and the keyboard: arrows, Home and
          End step through the years, and screen readers announce each one. */}
      <input
        type="range"
        min={0}
        max={last}
        step={1}
        value={active ?? last}
        aria-label={summarizeAreaChart(data)}
        aria-valuetext={`${formatSeriesValue(scrubbed.value, data.scale, false)} in ${scrubbed.year}`}
        onChange={(event) => setActive(Number(event.currentTarget.value))}
        onPointerMove={(event) =>
          setActive(
            indexAt(event.clientX, event.currentTarget.getBoundingClientRect())
          )
        }
        onPointerDown={(event) =>
          setActive(
            indexAt(event.clientX, event.currentTarget.getBoundingClientRect())
          )
        }
        onPointerLeave={() => setActive(null)}
        onFocus={() => setActive((current) => current ?? last)}
        onBlur={() => setActive(null)}
        className="absolute inset-0 size-full cursor-crosshair touch-pan-y appearance-none opacity-0"
      />
    </div>
  );
};

const AreaChartReady = ({
  data,
  showAsOf,
  tabs,
  onSelectTab,
}: {
  readonly data: AreaChartData;
  readonly showAsOf: boolean;
  readonly tabs?: Tabs;
  readonly onSelectTab: (id: string) => void;
}) => {
  const isUp = data.change >= 0;
  const sign = isUp ? "+" : "−";
  const changeTone = isUp
    ? "text-emerald-600 dark:text-emerald-400"
    : "text-red-600 dark:text-red-400";
  const tone = data.isPeriodTotal ? NEUTRAL_TONE : changeTone;

  return (
    <div className="flex flex-col gap-3">
      <header className="min-w-0">
        <p className="truncate text-sm font-semibold">
          {titleCase(data.topic)}
        </p>
      </header>

      {data.isPeriodTotal ? (
        <div className="flex items-baseline gap-2">
          <p className="text-2xl font-semibold tabular-nums">
            {formatSeriesValue(periodTotal(data), data.scale)}
          </p>
          <p className="text-muted-foreground text-sm tabular-nums">
            total, {formatPeriod(data)}
          </p>
        </div>
      ) : (
        <div className="flex items-baseline gap-2">
          <p className="text-2xl font-semibold tabular-nums">
            {formatSeriesValue(data.value, data.scale)}
          </p>
          <p className={cn("text-sm font-medium tabular-nums", tone)}>
            {sign}
            {formatChange(data)}
          </p>
        </div>
      )}

      <AreaPlot data={data} className={tone} />

      <div
        className={cn(
          "flex items-center gap-2",
          tabs ? "justify-between" : "justify-end"
        )}
      >
        {tabs ? (
          <fieldset className="bg-muted flex min-w-0 gap-0.5 overflow-x-auto rounded-lg p-0.5">
            <legend className="sr-only">{tabs.label}</legend>
            {tabs.items.map((item) => {
              const isSelected = item.id === tabs.selectedId;
              return (
                <button
                  key={item.id}
                  type="button"
                  aria-pressed={isSelected}
                  disabled={item.isDisabled}
                  onClick={() => onSelectTab(item.id)}
                  className={cn(
                    "focus-visible:ring-ring shrink-0 rounded-md px-2 py-0.5 text-xs font-medium whitespace-nowrap transition-colors outline-none focus-visible:ring-2 disabled:pointer-events-none disabled:opacity-40",
                    isSelected
                      ? "bg-background text-foreground shadow-sm"
                      : "text-muted-foreground hover:text-foreground"
                  )}
                >
                  {item.label}
                </button>
              );
            })}
          </fieldset>
        ) : null}
        {showAsOf && !data.subjects ? (
          <p className="text-muted-foreground shrink-0 text-xs">
            As of {formatAsOf(data.asOf)}
          </p>
        ) : null}
      </div>
    </div>
  );
};

const AreaChartError = ({
  topic,
  message = "The series service didn't respond. Try again in a moment.",
}: {
  readonly topic?: string;
  readonly message?: string;
}) => (
  <div role="alert" className="flex flex-col gap-1">
    <p className="text-sm font-semibold">
      {topic
        ? `Couldn't load a chart for ${titleCase(topic)}`
        : "Couldn't load the area chart"}
    </p>
    <p className="text-muted-foreground text-xs">{message}</p>
  </div>
);

/** The card while its data is on the way: the same frame and rows as the
 *  ready card, so nothing moves when the series lands. Shows the topic as
 *  soon as it's known (with "…" while the model is still writing it). */
export const AreaChartCardSkeleton = ({
  topic,
  streaming = false,
  className,
}: {
  readonly topic?: string;
  readonly streaming?: boolean;
  readonly className?: string;
}) => (
  <output className={cn(CARD_FRAME, "flex flex-col gap-3", className)}>
    <span className="sr-only">
      {topic ? `Loading a chart for ${topic}` : "Loading an area chart"}
    </span>
    {topic ? (
      <p aria-hidden className="truncate text-sm font-semibold">
        {titleCase(topic)}
        {streaming ? <span className="text-muted-foreground">…</span> : null}
      </p>
    ) : (
      <div aria-hidden className="flex h-5 items-center">
        <div className="bg-muted h-3.5 w-24 animate-pulse rounded" />
      </div>
    )}
    <div aria-hidden className="bg-muted h-8 w-40 animate-pulse rounded" />
    <div aria-hidden className="bg-muted h-24 w-full animate-pulse rounded" />
    <div aria-hidden className="bg-muted h-6 w-44 animate-pulse rounded-lg" />
  </output>
);

export const AreaChartCard = ({
  state,
  topic,
  data,
  error,
  series,
  showAsOf = true,
  className,
}: AreaChartCardProperties) => {
  const [selectedRange, setSelectedRange] = useState<AreaChartRange | null>(
    null
  );
  const [selectedSubject, setSelectedSubject] = useState<string | null>(null);
  const shown = shownData(data, series, selectedRange, selectedSubject);

  if (!(state === "error" || (state === "ready" && shown))) {
    return (
      <AreaChartCardSkeleton
        topic={topic}
        streaming={state === "streaming"}
        className={className}
      />
    );
  }
  if (state === "error" || !shown) {
    return (
      <div className={cn(CARD_FRAME, className)}>
        <AreaChartError topic={topic} message={error} />
      </div>
    );
  }
  return (
    <section
      aria-label={summarizeAreaChart(shown)}
      className={cn(CARD_FRAME, className)}
    >
      <AreaChartReady
        data={shown}
        showAsOf={showAsOf}
        tabs={tabsFor(shown, series)}
        onSelectTab={(id) => {
          if (hasSubjectTabs(shown)) {
            setSelectedSubject(id);
          } else if (isAreaChartRange(id)) {
            setSelectedRange(id);
          }
        }}
      />
    </section>
  );
};

"use client";

import { useEffect, useState } from "react";
import { AreaChartCard } from "@/features/area-chart/components/area-chart-card";
import { loadAreaChart } from "@/features/area-chart/area-chart-requests";
import {
  compareSubjects,
  withRange,
} from "@/features/area-chart/area-chart-schema";
import type {
  AreaChartData,
  AreaChartRange,
} from "@/features/area-chart/area-chart-schema";

/**
What came back for one request. A result for different props reads as still loading, so a new topic never flashes the old chart.
*/
type Result =
  | { key: string; status: "ready"; data: AreaChartData }
  | { key: string; status: "error"; message: string };

export const LiveAreaChartCard = ({
  topic,
  range,
  ranges = false,
  compare,
  streaming = false,
}: {
  readonly topic?: string;
  readonly range?: AreaChartRange;
  /**
  Model opt-in for the 10Y/25Y/50Y/Max tabs on long multi-decade series.
  */
  readonly ranges?: boolean;
  /**
  Model opt-in for subject tabs, e.g. ["Coal", "Solar"]. Takes the place of the range tabs.
  */
  readonly compare?: readonly string[];
  /**
  The model is still writing the card's props.
  */
  readonly streaming?: boolean;
}) => {
  const [result, setResult] = useState<Result | null>(null);
  const compareKey = compareSubjects(compare).join("\n");
  const isCompare = compareKey !== "";
  const isShowRanges = ranges === true && !isCompare;
  const initialRange = range ?? (isShowRanges ? "50y" : "max");
  const requestKey = [topic, initialRange, isShowRanges, compareKey].join("|");

  useEffect(() => {
    let isCancelled = false;
    const fetchRange = isShowRanges ? "max" : initialRange;
    const options = {
      compare: compareKey ? compareKey.split("\n") : [],
      ranges: isShowRanges,
    };
    const run = async (wanted: string) => {
      let next: Result;
      try {
        next = {
          data: await loadAreaChart(wanted, fetchRange, options),
          key: requestKey,
          status: "ready",
        };
      } catch (error) {
        next = {
          key: requestKey,
          message: Error.isError(error) ? error.message : "Area chart failed.",
          status: "error",
        };
      }
      if (!isCancelled) {
        setResult(next);
      }
    };
    if (!streaming && topic) {
      run(topic);
    }
    return () => {
      isCancelled = true;
    };
  }, [topic, initialRange, isShowRanges, compareKey, requestKey, streaming]);

  if (streaming || !topic) {
    return <AreaChartCard state="streaming" topic={topic} />;
  }
  const current = result?.key === requestKey ? result : null;
  if (current?.status === "ready") {
    return (
      <AreaChartCard
        state="ready"
        data={
          isShowRanges ? withRange(current.data, initialRange) : current.data
        }
        series={isShowRanges ? current.data : undefined}
      />
    );
  }
  return current?.status === "error" ? (
    <AreaChartCard state="error" topic={topic} error={current.message} />
  ) : (
    <AreaChartCard state="loading" topic={topic} />
  );
};

import { z } from "zod";
import { AREA_CHART_RANGES } from "@/features/area-chart/area-chart-schema";

export const areaChartCatalogEntry = {
  description:
    'A live area chart for questions about how a number changes over time (population, GDP, temperatures, energy share, prices, rates, and similar). The model writes a free-text topic from the user\'s ask; the card researches the web and draws the series. Never invent the numbers — the card fetches them. Not for a single total or a one-time breakdown by category ("what is US GDP by state?"): answer those with webSearch, since most sources give one figure per category, not a yearly series. Set ranges to true only when a long multi-decade series benefits from a 10Y/25Y/50Y/Max switch (e.g. world population, long GDP history). Leave ranges null/false for single-window answers. When the user asks for a yearly trend per subject — "each country", "per region", "compare X and Y" — set compare to 2–6 short tab labels for the biggest subjects (e.g. topic "US electricity share by source", compare ["Coal", "Gas", "Solar", "Wind"]); keep the topic about the whole and let each tab draw one subject\'s series. ranges is ignored with compare.',
  props: z.object({
    compare: z
      .array(z.string())
      .nullable()
      .describe(
        'Short tab labels (≤ 12 characters) for subjects to compare inside the topic, e.g. ["Coal", "Gas", "Solar", "Wind"] for "US electricity share by source". Null for a single series.'
      ),
    range: z
      .enum(AREA_CHART_RANGES)
      .nullable()
      .describe(
        "Window to show first when ranges is true: 10y, 25y, 50y, or max. Null for 50y. When ranges is false/null, null means the full series (max)."
      ),
    ranges: z
      .boolean()
      .nullable()
      .describe(
        "True only when the topic is a long multi-decade series that should offer 10Y/25Y/50Y/Max tabs (population, century-scale GDP, etc.). False or null hides the tabs — use that for most asks, recent series, and one-shot answers."
      ),
    topic: z
      .string()
      .describe(
        'What to chart, taken from the user\'s question — e.g. "world population", "US solar share of electricity", "global mean temperature anomaly", "Bitcoin yearly close".'
      ),
  }),
};

import { withRange } from "@/features/area-chart/area-chart-schema";
import type {
  AreaChartData,
  AreaChartRange,
} from "@/features/area-chart/area-chart-schema";

const sharedAreaChartRequests = new Map<
  string,
  { expiresAt: number; chart: Promise<AreaChartData> }
>();
const REUSE_MS = 120_000;

export interface LoadAreaChartOptions {
  /**
  When true, fetch the widest series once and filter client-side for the 10Y/25Y/50Y/Max tabs. When false, fetch only the requested window.
  */
  readonly ranges?: boolean;
  /**
  Subject tabs, e.g. ["Coal", "Solar"]. When given, one full series per subject comes back in `subjects`, and `range`/`ranges` don't apply.
  */
  readonly compare?: readonly string[];
}

function topicKey(topic: string) {
  return topic.trim().toLowerCase();
}

function cacheKey(
  topic: string,
  range: AreaChartRange,
  hasRanges: boolean,
  compare: readonly string[] = []
) {
  if (compare.length > 0) {
    return `${topicKey(topic)}|${compare.join("|").toLowerCase()}`;
  }
  return hasRanges ? topicKey(topic) : `${topicKey(topic)}:${range}`;
}

function areaChartUrl(
  topic: string,
  range: AreaChartRange,
  compare: readonly string[] = []
) {
  const parameters = new URLSearchParams({ range, topic });
  for (const subject of compare) {
    parameters.append("compare", subject);
  }
  return `/api/area-chart?${parameters}`;
}

async function fetchAreaChart(
  topic: string,
  range: AreaChartRange,
  compare: readonly string[]
) {
  const response = await fetch(areaChartUrl(topic, range, compare));
  const body = (await response.json()) as AreaChartData | { error: string };
  if (!response.ok || "error" in body) {
    throw new Error(
      "error" in body
        ? body.error
        : `Area chart request failed: ${response.status}`
    );
  }
  return body;
}

async function requestAreaChart(
  key: string,
  topic: string,
  range: AreaChartRange,
  compare: readonly string[]
) {
  try {
    return await fetchAreaChart(topic, range, compare);
  } catch (error) {
    sharedAreaChartRequests.delete(key);
    throw error;
  }
}

async function chartForRange(
  chart: Promise<AreaChartData>,
  range: AreaChartRange
) {
  const data = await chart;
  return withRange(data, range);
}

/**
Load an area-chart series. Pass `ranges: true` only when the card will show
the incremental window tabs — that path caches the full series by topic.
*/
export function loadAreaChart(
  topic: string,
  range: AreaChartRange,
  options: LoadAreaChartOptions = {}
) {
  const compare = options.compare ?? [];
  if (compare.length > 0) {
    const key = cacheKey(topic, "max", false, compare);
    const hit = sharedAreaChartRequests.get(key);
    if (hit && Date.now() < hit.expiresAt) {
      return hit.chart;
    }
    const chart = requestAreaChart(key, topic, "max", compare);
    sharedAreaChartRequests.set(key, {
      chart,
      expiresAt: Date.now() + REUSE_MS,
    });
    return chart;
  }
  const hasRanges = options.ranges === true;
  const key = cacheKey(topic, range, hasRanges);
  const hit = sharedAreaChartRequests.get(key);
  if (hit && Date.now() < hit.expiresAt) {
    return hasRanges ? chartForRange(hit.chart, range) : hit.chart;
  }
  const fetchRange = hasRanges ? "max" : range;
  const chart = requestAreaChart(key, topic, fetchRange, []);
  sharedAreaChartRequests.set(key, {
    chart,
    expiresAt: Date.now() + REUSE_MS,
  });
  return hasRanges ? chartForRange(chart, range) : chart;
}

/**
Seed the client cache from a docs recording. Always stores the exact window;
also stores a full-series entry when `range` is max so range tabs can filter.
A compare recording is stored under its subjects.
*/
export function primeAreaChart(
  topic: string,
  range: AreaChartRange,
  data: AreaChartData,
  compare: readonly string[] = []
) {
  if (compare.length > 0) {
    sharedAreaChartRequests.set(cacheKey(topic, range, false, compare), {
      chart: Promise.resolve(data),
      expiresAt: Infinity,
    });
    return;
  }
  sharedAreaChartRequests.set(cacheKey(topic, range, false), {
    chart: Promise.resolve(data),
    expiresAt: Infinity,
  });
  if (range === "max") {
    sharedAreaChartRequests.set(topicKey(topic), {
      chart: Promise.resolve({ ...data, range: "max" }),
      expiresAt: Infinity,
    });
  }
}

import { listOf } from "@/features/chat/lookup";
import { loadAreaChart } from "@/features/area-chart/area-chart-requests";
import {
  compareSubjects,
  isAreaChartRange,
  shouldShowAreaChartRanges,
} from "@/features/area-chart/area-chart-schema";
import { hostOf } from "@/lib/url-host";
import type { AreaChartRange } from "@/features/area-chart/area-chart-schema";
import type { CardLookup, Source } from "@/features/chat/lookup";

function topicFromProperties(properties: Record<string, unknown>): string {
  if (typeof properties.topic === "string") {
    return properties.topic;
  }
  return typeof properties.place === "string" ? properties.place : "";
}

function defaultRange(hasRanges: boolean): AreaChartRange {
  return hasRanges ? "50y" : "max";
}

function propertiesOf(properties: Record<string, unknown>) {
  const hasRanges = shouldShowAreaChartRanges(properties.ranges);
  return {
    compare: compareSubjects(properties.compare),
    hasRanges,
    range: isAreaChartRange(properties.range)
      ? properties.range
      : defaultRange(hasRanges),
    topic: topicFromProperties(properties),
  };
}

function researchSources(result: unknown): readonly Source[] {
  if (!result || typeof result !== "object") {
    return [];
  }
  const { sourceHref, sourceLabel } = result as {
    sourceHref?: unknown;
    sourceLabel?: unknown;
  };
  if (typeof sourceHref !== "string" || !sourceHref) {
    return [];
  }
  const label =
    typeof sourceLabel === "string" && sourceLabel.trim()
      ? sourceLabel.trim()
      : hostOf(sourceHref);
  return [{ href: sourceHref, label }];
}

export const areaChartLookup: CardLookup = {
  intent: (topics) =>
    topics.length === 1
      ? `The trend of ${topics[0]}`
      : `Trends for ${listOf(topics)}`,
  load: (properties) => {
    const { compare, topic, range, hasRanges } = propertiesOf(properties);
    return topic
      ? loadAreaChart(topic, range, { compare, ranges: hasRanges })
      : Promise.reject(
          new Error(
            'Pass a topic, for example "US solar share of electricity".'
          )
        );
  },
  resultSources: researchSources,
  sources: () => [
    {
      href: "https://parallel.ai",
      label: "parallel.ai",
    },
  ],
  subject: (properties) => {
    const topic = propertiesOf(properties).topic.trim();
    return topic || null;
  },
};

import "server-only";
import {
  createExtractTool,
  createSearchTool,
} from "@parallel-web/ai-sdk-tools";
import { generateText, isStepCount, Output } from "ai";
import {
  areaChartSeriesSchema,
  withRange,
} from "@/features/area-chart/area-chart-schema";
import type {
  AreaChartData,
  AreaChartPoint,
  AreaChartRange,
  AreaChartSeriesResult,
  AreaChartSubject,
} from "@/features/area-chart/area-chart-schema";

/**
Research copies long data tables into numbers, where Haiku 4.5 misreads
rows (it returned 13.7B people for 2025). Separate from the chat model.
*/
const DEFAULT_RESEARCH_MODEL = "anthropic/claude-haiku-5.5";

interface Budget {
  /**
  Tool steps before the model must answer. Step 0 is forced to search and step 1 to extract, so the numbers come from a page rather than memory; without a forced final answer the model keeps digging and returns nothing.
  */
  readonly steps: number;
  readonly timeoutMs: number;
}

const SERIES_BUDGET: Budget = { steps: 5, timeoutMs: 55_000 };
const COMPARE_BUDGET: Budget = { steps: 7, timeoutMs: 85_000 };
const EARLIEST_YEAR = 1800;
/**
Parallel serves cached pages by default; an extracted page older than a day is fetched live so a data table's newest release isn't missed. Search keeps the cache: a live search costs ~8s a call against ~1.5s, and it only picks URLs.
*/
const LIVE_FETCH_MAX_AGE_S = 86_400;

export class AreaChartNotFoundError extends Error {
  constructor(topic: string, options?: ErrorOptions) {
    super(`No area chart series found for "${topic}".`, options);
    this.name = "AreaChartNotFoundError";
  }
}

interface ResearchOptions {
  readonly stale?: AreaChartData;
  readonly subject?: string;
}

interface Research {
  readonly data: AreaChartData;
  readonly isOngoing: boolean;
}

function freshYear(): number {
  const today = new Date();
  return today.getUTCFullYear() - 1;
}

function latestYear(data: AreaChartData): number {
  return data.points.at(-1)?.year ?? 0;
}

function isStale({ data, isOngoing }: Research): boolean {
  return isOngoing && latestYear(data) < freshYear();
}

function staleNote(stale: AreaChartData): string {
  const source = stale.sourceHref
    ? `${stale.sourceLabel ?? "a source"} (${stale.sourceHref})`
    : (stale.sourceLabel ?? "a source");
  return `\n\nA previous attempt used ${source}, whose data stops in ${latestYear(stale)}. That is outdated. Find a different source that publishes ${freshYear()} or later, and use it for the whole series.`;
}

function subjectNote(subject?: string): string {
  return subject
    ? `\nSubject: ${subject} — chart only this subject's figures. Total or World means the sum across everyone. If no source gives yearly figures for it, fail rather than estimating.`
    : "";
}

function researchPrompt(
  topic: string,
  range: AreaChartRange,
  steps: number,
  { stale, subject }: ResearchOptions
): string {
  const today = new Date();
  const year = today.getUTCFullYear();
  const window =
    range === "max"
      ? `as many years as reliable public data allows, starting no earlier than ${EARLIEST_YEAR}`
      : `about the last ${{ "10y": "10", "25y": "25", "50y": "50" }[range]} years, plus earlier points if they help the trend`;

  return `Today is ${today.toISOString().slice(0, 10)}. Find a real public time series that answers this as an area chart:

Topic: ${topic}${subjectNote(subject)}

Requirements:
- Prefer official or well-known statistical sources (World Bank, OECD, Our World in Data, UN, NASA, national stats offices, reputable market data pages, standard reference works for history).
- Search first, then extract the best URL(s) — a data table, CSV or JSON API, not an article — and copy the numbers from it.
- Freshness matters most for a measure that is still published: the series must reach ${year - 1} (or ${year} for monthly, daily or market data). Among sources, pick the one whose latest year is newest — aggregators such as Our World in Data often lag the original publisher by a year or two. For country or world indicators the World Bank API is current: https://api.worldbank.org/v2/country/<ISO3 or WLD>/indicator/<indicator code>?format=json&per_page=100. A finished period instead covers every year it lasted, first to last: if a source is missing years, find one that has them all, or fail.
- Cover ${window}.
- Exactly one point per year: copy every year in the table, don't sample every 5 or 10 years. When a source splits a year into parts, add them up into that year's one value. Month→year averages are fine. Years before the last 50 can be sparser.
- Oldest first, numeric values only (no units inside the number).
- scale: "percent" for rates/shares, "currency" for money in USD, otherwise "number".
- You have ${steps} tool steps, then you must answer from what you extracted.
- If the topic cannot be turned into a numeric time series, fail rather than inventing numbers.${stale ? staleNote(stale) : ""}`;
}

function cleanPoints(points: readonly AreaChartPoint[]): AreaChartPoint[] {
  const byYear = new Map<number, number>();
  for (const { year, value } of points) {
    if (
      Number.isFinite(year) &&
      Number.isFinite(value) &&
      year >= EARLIEST_YEAR
    ) {
      byYear.set(year, value);
    }
  }
  return [...byYear]
    .map(([year, value]) => ({ value, year }))
    .toSorted((left, right) => left.year - right.year);
}

function toAreaChartData(
  query: string,
  range: AreaChartRange,
  output: AreaChartSeriesResult
): AreaChartData {
  const points = cleanPoints(output.points);
  if (points.length < 2) {
    throw new AreaChartNotFoundError(query);
  }
  return withRange(
    {
      asOf: Date.now(),
      change: 0,
      changePercent: 0,
      fake: false,
      isPeriodTotal: output.additive && !output.ongoing,
      label: output.label.trim() || "Series",
      place: output.place.trim() || query,
      points,
      range: "max",
      scale: output.scale,
      sourceHref: output.sourceHref ?? undefined,
      sourceLabel: output.sourceLabel ?? undefined,
      topic: query,
      value: 0,
    },
    range
  );
}

async function researchOnce(
  query: string,
  range: AreaChartRange,
  abortSignal: AbortSignal,
  options: ResearchOptions
): Promise<Research> {
  const { steps } = options.subject ? COMPARE_BUDGET : SERIES_BUDGET;
  const model = process.env.AREA_CHART_MODEL || DEFAULT_RESEARCH_MODEL;
  const webSearch = createSearchTool({
    client_model: model,
    max_results: 8,
    mode: "advanced",
  });
  const webExtract = createExtractTool({
    client_model: model,
    fetch_policy: { max_age_seconds: LIVE_FETCH_MAX_AGE_S },
  });

  const { output } = await generateText({
    abortSignal,
    instructions:
      "You turn questions into honest yearly time series for a generative UI area chart. Never invent, interpolate or recall figures from memory: every value must come from a page you extracted.",
    model,
    output: Output.object({ schema: areaChartSeriesSchema }),
    prepareStep: ({ stepNumber }) => {
      if (stepNumber === 0) {
        return { toolChoice: { toolName: "webSearch", type: "tool" } };
      }
      if (stepNumber === 1) {
        return { toolChoice: { toolName: "webExtract", type: "tool" } };
      }
      return stepNumber >= steps ? { toolChoice: "none" } : {};
    },
    prompt: researchPrompt(query, range, steps, options),
    stopWhen: isStepCount(steps + 1),
    tools: {
      webExtract,
      webSearch,
    },
  });

  if (!output?.points?.length) {
    throw new AreaChartNotFoundError(query);
  }

  return {
    data: toAreaChartData(query, range, output),
    isOngoing: output.ongoing,
  };
}

async function researchAreaChart(
  query: string,
  range: AreaChartRange,
  subject?: string
): Promise<AreaChartData> {
  const { timeoutMs } = subject ? COMPARE_BUDGET : SERIES_BUDGET;
  const abortSignal = AbortSignal.timeout(timeoutMs);
  let first: Research;
  try {
    first = await researchOnce(query, range, abortSignal, { subject });
  } catch (error) {
    if (abortSignal.aborted) {
      throw error;
    }
    const retry = await researchOnce(query, range, abortSignal, { subject });
    return retry.data;
  }
  if (!isStale(first)) {
    return first.data;
  }
  let second = first;
  try {
    second = await researchOnce(query, range, abortSignal, {
      stale: first.data,
      subject,
    });
  } catch (error) {
    if (abortSignal.aborted) {
      throw error;
    }
  }
  return latestYear(second.data) > latestYear(first.data)
    ? second.data
    : first.data;
}

function hasGaps(points: readonly AreaChartPoint[]): boolean {
  return points.some(
    (point, index) => index > 0 && point.year - points[index - 1].year > 1
  );
}

async function researchCompare(
  query: string,
  compare: readonly string[]
): Promise<AreaChartData> {
  const results = await Promise.allSettled(
    compare.map((name) => researchAreaChart(query, "max", name))
  );
  const found: { data: AreaChartData; subject: AreaChartSubject }[] = [];
  for (const [index, result] of results.entries()) {
    if (result.status === "fulfilled" && !hasGaps(result.value.points)) {
      found.push({
        data: result.value,
        subject: { name: compare[index], points: result.value.points },
      });
    }
  }
  const [first] = found;
  if (!first) {
    throw new AreaChartNotFoundError(query);
  }
  return {
    ...first.data,
    place: first.subject.name,
    subjects: found.map(({ subject }) => subject),
  };
}

/**
Research a free-text topic on the web (Parallel search + extract) and shape
it into an area-chart series. With `compare`, one series per subject comes
back for the card's tabs.
*/
export async function getAreaChart(
  topic: string,
  range: AreaChartRange = "50y",
  compare: readonly string[] = []
): Promise<AreaChartData> {
  const query = topic.trim();
  if (!query) {
    throw new AreaChartNotFoundError(topic);
  }
  if (!process.env.PARALLEL_API_KEY) {
    throw new Error(
      "PARALLEL_API_KEY is missing. Add it to .env.local to load live area charts."
    );
  }

  const research =
    compare.length > 0
      ? () => researchCompare(query, compare)
      : () => researchAreaChart(query, range);
  try {
    return await research();
  } catch (error) {
    if (error instanceof AreaChartNotFoundError) {
      throw error;
    }
    if (Error.isError(error) && /PARALLEL_API_KEY/u.test(error.message)) {
      throw error;
    }
    throw new AreaChartNotFoundError(query, { cause: error });
  }
}

import { z } from "zod";

export const AREA_CHART_RANGES = ["10y", "25y", "50y", "max"] as const;
export type AreaChartRange = (typeof AREA_CHART_RANGES)[number];

export const AREA_CHART_SCALES = ["number", "percent", "currency"] as const;
export type AreaChartScale = (typeof AREA_CHART_SCALES)[number];

export const RANGE_LABEL: Record<AreaChartRange, string> = {
  "10y": "10Y",
  "25y": "25Y",
  "50y": "50Y",
  max: "Max",
};

export function isAreaChartRange(value: unknown): value is AreaChartRange {
  return (
    typeof value === "string" &&
    (AREA_CHART_RANGES as readonly string[]).includes(value)
  );
}

/**
Most subject tabs a compare card shows; more won't fit the card's width.
*/
export const MAX_COMPARE = 6;

/**
Cleans the model's compare labels: trimmed, no blanks or repeats, at most MAX_COMPARE. Fewer than two subjects means there's nothing to compare.
*/
export function compareSubjects(value: unknown): string[] {
  if (!Array.isArray(value)) {
    return [];
  }
  const subjects = [
    ...new Set(
      value
        .filter((item): item is string => typeof item === "string")
        .map((item) => item.trim())
        .filter(Boolean)
    ),
  ].slice(0, MAX_COMPARE);
  return subjects.length >= 2 ? subjects : [];
}

/**
What the model sends: the tool's input.
*/
export const areaChartInputSchema = z.object({
  compare: z
