/**
A linear congruential generator (Numerical Recipes' constants) seeded from a string, so a topic always gets the same demo series. Every product stays under 2^53, so plain arithmetic is exact.
*/
const LCG_MODULUS = 2 ** 32;
const LCG_MULTIPLIER = 1_664_525;
const LCG_INCREMENT = 1_013_904_223;
const SEED_BASE = 31;

function seeded(seed: string) {
  let state = 0;
  for (const char of seed) {
    state = (state * SEED_BASE + (char.codePointAt(0) ?? 0)) % LCG_MODULUS;
  }
  return () => {
    state = (state * LCG_MULTIPLIER + LCG_INCREMENT) % LCG_MODULUS;
    return state / LCG_MODULUS;
  };
}

/**
Demo series for offline tests. Not used by the live World/Parallel path.
*/
export function fakeAreaChart(
  topic: string,
  range: AreaChartRange = "50y",
  now = Date.UTC(2026, 9, 17, 12, 0)
): AreaChartData {
  const query = topic.trim() || "demo series";
  const random = seeded(query.toLowerCase());
  const scale = 0.5 + random();
  const points = DEMO_POINTS.map((point) => ({
    value: Math.round(point.value * scale),
    year: point.year,
  }));
  const base: AreaChartData = {
    asOf: now,
    change: 0,
    changePercent: 0,
    fake: true,
    label: "Series",
    place: query,
    points,
    range: "max",
    scale: "number",
    topic: query,
    value: 0,
  };
  return withRange(base, range);
}

import {
  AreaChartNotFoundError,
  getAreaChart,
} from "@/features/area-chart/area-chart-queries";
import {
  AREA_CHART_RANGES,
  compareSubjects,
} from "@/features/area-chart/area-chart-schema";
import type { AreaChartRange } from "@/features/area-chart/area-chart-schema";

// Compare subjects research in parallel for up to 85s (COMPARE_BUDGET).
export const maxDuration = 90;

const CACHE = "public, s-maxage=300, stale-while-revalidate=3600";

// eslint-disable-next-line sonarjs/function-name -- Next.js route handlers must be named after the HTTP method
export async function GET(request: Request) {
  const { searchParams } = new URL(request.url);
  const topic =
    searchParams.get("topic")?.trim() ||
    searchParams.get("place")?.trim() ||
    "";
  const range = searchParams.get("range") ?? "max";

  if (!topic || !(AREA_CHART_RANGES as readonly string[]).includes(range)) {
    return Response.json(
      {
        error:
          "Pass a topic (any chartable question) and a range of 10y, 25y, 50y or max.",
      },
      { status: 400 }
    );
  }

  const compare = compareSubjects(searchParams.getAll("compare"));
  try {
    const data = await getAreaChart(topic, range as AreaChartRange, compare);
    return Response.json(data, {
      headers: { "Cache-Control": CACHE },
    });
  } catch (error) {
    const status = error instanceof AreaChartNotFoundError ? 404 : 502;
    return Response.json(
      {
        error: Error.isError(error) ? error.message : "Area chart failed.",
      },
      { status }
    );
  }
}

